class LoggingSettingsView extends ConsumerStatefulWidget {
  const LoggingSettingsView({super.key});

  static const String routeName = "/loggingView";

  @override
  ConsumerState<LoggingSettingsView> createState() =>
      _LoggingSettingsViewState();
}

class _LoggingSettingsViewState extends ConsumerState<LoggingSettingsView> {
  late final TextEditingController fileLocationController;
  bool _lock = false;

  Future<void> _edit() async {
    final currentPath =
        ref.read(prefsChangeNotifierProvider).logsPath ??
        Logging.instance.logsDirPath;
    final newPath = await _pickDir(context, currentPath);

    // test if has permission to write
    if (newPath != null) {
      final file = File("$newPath${Platform.pathSeparator}._test");
      if (!file.existsSync()) {
        file.createSync();
        file.deleteSync();
      }
    }

    // success
    ref.read(prefsChangeNotifierProvider).logsPath = newPath;

    if (mounted) {
      setState(() {
        fileLocationController.text =
            ref.read(prefsChangeNotifierProvider).logsPath ??
            Logging.instance.logsDirPath;
      });
    }
  }

  Future<String?> _pickDir(BuildContext context, String currentPath) async {
    final String? chosenPath;
    // if (Platform.isIOS) {
    //   chosenPath = currentPath;
    // } else {
    final String path =
        Platform.isWindows ? currentPath.replaceAll("/", "\\") : currentPath;
    chosenPath = await FilePicker.platform.getDirectoryPath(
      dialogTitle: appL10n.settingsLogsChooseLocationDialog,
      initialDirectory: path,
      lockParentWindow: true,
    );
    // }
    return chosenPath;
  }

  Future<void> _exportHelper() async {
    final logsDir = await StackFileSystem.applicationLogsDirectory(
      ref.read(prefsChangeNotifierProvider),
    );

    final files = logsDir
        .listSync(recursive: false)
        .whereType<File>()
        .where((f) => f.path.endsWith('.txt'));

    if (files.isEmpty) {
      throw Exception(appL10n.settingsLogsNoneFound(logsDir.path));
    }

    final archive = Archive();

    for (final file in files) {
      final bytes = await file.readAsBytes();
      final fileName = path.basename(file.path);
      archive.addFile(ArchiveFile(fileName, bytes.length, bytes));
    }

    if (archive.isEmpty) {
      throw Exception(appL10n.settingsLogsArchiveFailed);
    }

    // Write zip to a temp location
    final tempDir = await getTemporaryDirectory();
    final zipPath = path.join(tempDir.path, 'logs.zip');
    final zipFile = File(zipPath);
    await zipFile.writeAsBytes(ZipEncoder().encode(archive)!);

    await Share.shareXFiles([
      XFile(zipFile.path),
    ], text: appL10n.settingsLogsShareText(AppConfig.appName));
  }

  bool _exportLock = false;
  Future<void> _androidExportLogs() async {
    if (_exportLock) {
      return;
    }
    _exportLock = true;
    try {
      await showLoading(
        whileFuture: _exportHelper(),
        context: context,
        message: context.l10n.settingsLogsExporting,
        onException: (e) => throw e,
      );
    } catch (e, s) {
      Logging.instance.e("Failed to export logs", error: e, stackTrace: s);
      if (mounted) {
        unawaited(
          showDialog(
            context: context,
            builder:
                (context) => StackOkDialog(
                  title: context.l10n.settingsLogsExportFailed,
                  message: e.toString(),
                ),
          ),
        );
      }
    } finally {
      _exportLock = false;
    }
  }

  @override
  void initState() {
    super.initState();
    fileLocationController = TextEditingController();
    fileLocationController.text =
        ref.read(prefsChangeNotifierProvider).logsPath ??
        Logging.instance.logsDirPath;
  }

  @override
  void dispose() {
    fileLocationController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          leading: AppBarBackButton(
            onPressed: () async {
              Navigator.of(context).pop();
            },
          ),
          title: Text(context.l10n.settingsLogging, style: STextStyles.navBarTitle(context)),
        ),
        body: SafeArea(
          child: Padding(
            padding: const EdgeInsets.only(top: 12, left: 16, right: 16),
            child: Column(
              children: [
                Row(
                  children: [
                    Text(
                      context.l10n.settingsLogsLocationLabel,
                      style: STextStyles.fieldLabel(context),
                      textAlign: TextAlign.left,
                    ),
                  ],
                ),
                const SizedBox(height: 16),
                TextField(
                  autocorrect: false,
                  enableSuggestions: false,
                  controller: fileLocationController,
                  style: STextStyles.field(context),
                  decoration: InputDecoration(
                    hintText: context.l10n.settingsLogsSaveToHint,
                    hintStyle: STextStyles.fieldLabel(context),
                    suffixIcon: UnconstrainedBox(
                      child: Row(
                        children: [
                          const SizedBox(width: 16),
                          SvgPicture.asset(
                            Assets.svg.folder,
                            color:
                                Theme.of(
                                  context,
                                ).extension<StackColors>()!.textDark3,
                            width: 16,
                            height: 16,
                          ),
                          const SizedBox(width: 12),
                        ],
                      ),
                    ),
                  ),
                  key: const Key("logsDirPathLocationControllerKey"),
                  readOnly: true,
                  toolbarOptions: const ToolbarOptions(
                    copy: true,
                    cut: false,
                    paste: false,
                    selectAll: false,
                  ),
                  onChanged: (newValue) {},
                ),
                const SizedBox(height: 16),
                const LogLevelPreferenceWidget(),
                const SizedBox(height: 16),
                Row(
                  children: [
                    Expanded(
                      child: RoundedWhiteContainer(
                        child: Text(
                          context.l10n.settingsLogsRestartNote(AppConfig.appName),
                          style: STextStyles.subtitle500(context),
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 16),
                const Spacer(),

                if (Platform.isAndroid)
                  SecondaryButton(
                    label: context.l10n.settingsLogsExport,
                    onPressed: _androidExportLogs,
                  ),
                if (Platform.isAndroid) const SizedBox(height: 16),

                PrimaryButton(
                  label: context.l10n.settingsLogsSelectLocation,
                  onPressed: () async {
                    if (_lock) {
                      return;
                    }
                    _lock = true;
                    try {
                      await _edit();
                    } catch (e, s) {
                      Logging.instance.e(
                        "Failed to change logs path",
                        error: e,
                        stackTrace: s,
                      );
                      if (context.mounted) {
                        final String err;
                        if (e.toString().contains(
                          "OS Error: Operation not permitted",
                        )) {
                          err = context.l10n.settingsLogsCannotUseLocation;
                        } else {
                          err = e.toString();
                        }

                        unawaited(
                          showDialog(
                            context: context,
                            builder:
                                (context) => StackOkDialog(
                                  title: context.l10n.settingsLogsChangePathFailed,
                                  message: err,
                                ),
                          ),
                        );
                      }
                    } finally {
                      _lock = false;
                    }
                  },
                ),
                const SizedBox(height: 16),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
